/// previous, unchecked, behavior use
/// `size_prefixed_root_as_table_unchecked`.
pub fn size_prefixed_root_as_table(buf: &[u8]) -> Result<Table, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::size_prefixed_root::<Table>(buf)
}
#[inline]
/// Verifies, with the given options, that a buffer of bytes
/// contains a `Table` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_table_unchecked`.
pub fn root_as_table_with_opts<'b, 'o>(
    opts: &'o flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<Table<'b>, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::root_with_opts::<Table<'b>>(opts, buf)
}
#[inline]
/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `Table` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_table_unchecked`.
pub fn size_prefixed_root_as_table_with_opts<'b, 'o>(
    opts: &'o flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<Table<'b>, flatbuffers::InvalidFlatbuffer> {
    flatbuffers::size_prefixed_root_with_opts::<Table<'b>>(opts, buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a Table and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `Table`.
pub unsafe fn root_as_table_unchecked(buf: &[u8]) -> Table {
    flatbuffers::root_unchecked::<Table>(buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed Table and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `Table`.
pub unsafe fn size_prefixed_root_as_table_unchecked(buf: &[u8]) -> Table {
    flatbuffers::size_prefixed_root_unchecked::<Table>(buf)
}
pub const TABLE_IDENTIFIER: &str = "COLL";

#[inline]
pub fn table_buffer_has_identifier(buf: &[u8]) -> bool {
    flatbuffers::buffer_has_identifier(buf, TABLE_IDENTIFIER, false)
}

#[inline]
pub fn table_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    flatbuffers::buffer_has_identifier(buf, TABLE_IDENTIFIER, true)
}

#[inline]
pub fn finish_table_buffer<'a, 'b>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>,
    root: flatbuffers::WIPOffset<Table<'a>>,
) {
    fbb.finish(root, Some(TABLE_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_table_buffer<'a, 'b>(
    fbb: &'b mut flatbuffers::FlatBufferBuilder<'a>,
    root: flatbuffers::WIPOffset<Table<'a>>,
) {
    fbb.finish_size_prefixed(root, Some(TABLE_IDENTIFIER));
}
